// Mini piyano: 4 buton 4 nota çalar; çalan notanın LED'i yanar.
const int BUTONLAR[] = {5, 4, 3, 2};          // Do, Re, Mi, Fa butonları (öbür uçları GND'de)
const int LEDLER[] = {11, 10, 9, 8};          // her butonun kendi LED'i
const int NOTALAR[] = {262, 294, 330, 349};   // frekans (Hz): Do, Re, Mi, Fa
const char* NOTA_ADI[] = {"Do", "Re", "Mi", "Fa"};
const int ADET = 4;
const int BUZZER_PIN = 12;

int calan = -1;  // çalan notanın sırası; -1: sessiz

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < ADET; i++) {
    pinMode(BUTONLAR[i], INPUT_PULLUP);
    pinMode(LEDLER[i], OUTPUT);
  }
}

void loop() {
  // Basılı ilk butonu bul. Basılı buton LOW okunur.
  int basilan = -1;
  for (int i = 0; i < ADET; i++) {
    if (digitalRead(BUTONLAR[i]) == LOW) {
      basilan = i;
      break;
    }
  }

  // Yalnız durum değişince sesi ve LED'leri güncelle.
  if (basilan != calan) {
    for (int i = 0; i < ADET; i++) {
      digitalWrite(LEDLER[i], i == basilan ? HIGH : LOW);
    }
    if (basilan >= 0) {
      tone(BUZZER_PIN, NOTALAR[basilan]);
      Serial.println(NOTA_ADI[basilan]);
    } else {
      noTone(BUZZER_PIN);
    }
    calan = basilan;
  }
  delay(10);  // buton sıçramasını azaltır
}
